<script setup>
import {ref,reactive,computed,watch,inject} from 'vue'
import {useAuthStore} from '../../../stores/auth'
import {useOrderBranches} from '../../../composables/useOrderBranches'
import {useApiState,useApiMutation} from '../../../composables/useApiState'
import {useUnsavedForm} from '../../../composables/useUnsavedForm'
import {branchesApi} from '../../../api/branches.api'
import {operationsApi} from '../../../api/operations.api'
import BusinessHoursPanel from './BusinessHoursPanel.vue'
import ClosuresPanel from './ClosuresPanel.vue'
import AdminSectionHeading from '../AdminSectionHeading.vue'
import AdminModal from '../AdminModal.vue'
import ApiFeedback from '../catalog/ApiFeedback.vue'
const props=defineProps({branchId:String}),emit=defineEmits(['updated'])
const auth=useAuthStore(),{branches,loading:branchesLoading,error:branchError}=useOrderBranches(),selected=ref(props.branchId||''),state=useApiState(),mutation=useApiMutation(),{notify}=inject('admin')
const form=reactive({accepts_orders:false,supports_pickup:false,supports_delivery:false}),baseline=ref(''),confirmation=ref(false),saving=ref(false),hoursDirty=ref(false),closuresDirty=ref(false),hoursBusy=ref(false),closuresBusy=ref(false)
const dirty=computed(()=>!!state.data.value&&auth.can('branches.view')&&JSON.stringify(form)!==baseline.value)
const blocked=computed(()=>saving.value||hoursBusy.value||closuresBusy.value||dirty.value||hoursDirty.value||closuresDirty.value)
useUnsavedForm(dirty,saving)
const availability=computed(()=>auth.can('branches.view')?state.data.value?.availability:state.data.value)
async function load(preserveDraft=false){const id=selected.value,keepDraft=preserveDraft===true&&dirty.value;if(!id)return;const result=await state.run(signal=>auth.can('branches.view')?branchesApi.show(id):operationsApi.status(id,signal));if(id!==selected.value)return;if(result&&auth.can('branches.view')){const snapshot=Object.fromEntries(Object.keys(form).map(key=>[key,result[key]]));if(!keepDraft)Object.assign(form,snapshot);baseline.value=JSON.stringify(snapshot)}}
watch(branches,values=>{if(!selected.value)selected.value=values[0]?.id||''})
watch(selected,load,{immediate:true})
function reset(){Object.assign(form,JSON.parse(baseline.value));mutation.error.value=null}
async function save(){if(saving.value)return;saving.value=true;try{const body=Object.fromEntries(Object.entries(form).filter(([key,value])=>value!==JSON.parse(baseline.value)[key]));const result=await mutation.run(()=>branchesApi.update(selected.value,body));if(result.ok){confirmation.value=false;notify('تم حفظ إعدادات تشغيل الفرع.');await load();emit('updated')}}finally{saving.value=false}}
function updated(){load(true);emit('updated')}
</script>
<template><div class="branch-operations"><section class="panel branch-control-panel"><AdminSectionHeading icon="map-pin">تشغيل الفروع<template #actions><button class="row-button" type="button" :disabled="blocked||state.loading.value||!selected" @click="load">تحديث الحالة</button></template></AdminSectionHeading><p class="settings-section-intro">اختر الفرع لمراجعة حالته وضبط استقبال الطلبات وساعات العمل والإغلاقات المؤقتة.</p><div class="branch-selector"><label v-if="!branchId" class="field">الفرع<select v-model="selected" :disabled="branchesLoading||blocked"><option value="">اختر الفرع</option><option v-for="branch in branches" :key="branch.id" :value="branch.id">{{ branch.name }}{{ branch.is_active?'':' (غير نشط)' }}</option></select></label><p v-if="blocked" class="form-note">احفظ التغييرات أو تراجع عنها قبل تغيير الفرع.</p></div><p v-if="!selected&&!branchesLoading" class="branch-empty-state">اختر فرعًا لعرض إعدادات التشغيل.</p><ApiFeedback variant="detail" :loading="branchesLoading||state.loading.value" :error="branchError||state.error.value" @retry="load"/><template v-if="state.data.value"><div v-if="availability" class="branch-status-summary"><h3>حالة الفرع الآن</h3><div class="catalog-tags"><span class="badge" :class="availability.is_open?'good':'off'">{{ availability.is_open?'مفتوح حسب الجدول':'مغلق حسب الجدول' }}</span><span class="badge" :class="availability.accepts_orders?'good':'off'">{{ availability.accepts_orders?'يستقبل الطلبات الآن':'لا يستقبل الطلبات الآن' }}</span><span class="badge">الاستلام: {{ availability.pickup?.available?'متاح':'غير متاح' }}</span><span class="badge">التوصيل: {{ availability.delivery?.available?'متاح':'غير متاح' }}</span></div></div><p v-else role="status">حالة التشغيل غير متاحة؛ حدّث بيانات الفرع.</p><p v-if="availability?.reason" role="status">{{ availability.reason.message }}</p><p v-if="availability?.next_opening_at">موعد الفتح القادم من الخادم (UTC): <bdi>{{ availability.next_opening_at }}</bdi></p><form v-if="auth.can('branches.view')" @submit.prevent="confirmation=true"><fieldset class="settings-fields" :disabled="saving||!auth.can('branches.update')"><h3 class="branch-controls-title">خدمات الفرع</h3><div class="form-grid"><label v-for="[key,label] in [['accepts_orders','السماح للفرع باستقبال الطلبات'],['supports_pickup','دعم الاستلام'],['supports_delivery','دعم التوصيل']]" :key="key" class="check"><input v-model="form[key]" :name="key" type="checkbox">{{ label }}</label></div></fieldset><p class="form-note">نشاط الفرع إداريًا مستقل عن ساعات العمل واستقبال الطلبات. الحالة الفعلية أعلاه يحددها الخادم.</p><div class="form-actions"><button v-if="auth.can('branches.update')" class="button" :disabled="saving||!dirty">حفظ تشغيل الفرع</button><button type="button" class="row-button" :disabled="saving||!dirty" @click="reset">تراجع</button></div></form></template><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></section>
<BusinessHoursPanel v-if="selected&&auth.can('branches.hours.view')" :key="selected+'-hours'" :branch="selected" @updated="updated" @dirty="hoursDirty=$event" @busy="hoursBusy=$event"/>
<ClosuresPanel v-if="selected&&auth.can('branches.closures.view')" :key="selected+'-closures'" :branch="selected" @updated="updated" @dirty="closuresDirty=$event" @busy="closuresBusy=$event"/>
<AdminModal :open="confirmation" title="تأكيد تشغيل الفرع" :busy="saving" @update:open="confirmation=$event" @submit="save"><p>ستُطبق حالة استقبال الطلبات ودعم الاستلام والتوصيل على هذا الفرع. قد يؤدي تعطيلها إلى توقف الطلبات الجديدة.</p><button class="button" :disabled="saving">{{ saving?'جارٍ الحفظ…':'تأكيد وحفظ' }}</button><ApiFeedback :error="mutation.error.value" @retry="mutation.error.value=null"/></AdminModal></div></template>
